/** Observation only. Never tags values, propagates labels, or decides origins. */
public final class NativeBoundaryFactsAgent implements ClassFileTransformer,Opcodes {
 static String prefix;static Path output;static long seq,callId;static boolean invalid;
 static final Set<String> reads=new HashSet<>(),sinks=new HashSet<>();
 static final ThreadLocal<Deque<Map<String,Object>>> calls=new ThreadLocal<Deque<Map<String,Object>>>(){protected Deque<Map<String,Object>>initialValue(){return new ArrayDeque<>();}};
 static final IdentityHashMap<ClassLoader,Map<String,String>> definitions=new IdentityHashMap<>();
 static final Set<String> runtimeClasses=new HashSet<>(Arrays.asList("com/google/gson/Gson","org/springframework/http/converter/json/GsonHttpMessageConverter"));
 public static void premain(String arg,Instrumentation inst)throws Exception{
  Map cfg=new com.google.gson.Gson().fromJson(new String(Files.readAllBytes(Paths.get(System.getProperty("boundary.config"))),StandardCharsets.UTF_8),Map.class);
  prefix=(String)cfg.get("prefix");reads.addAll((List<String>)cfg.get("source_calls"));sinks.addAll((List<String>)cfg.get("sink_calls"));output=Paths.get(System.getProperty("boundary.events"));Files.createFile(output);
  inst.addTransformer(new NativeBoundaryFactsAgent());emit("start",Collections.singletonMap("scope","Raw call/argument/version/library facts; no native propagation change or certified JSON projection"));
  Runtime.getRuntime().addShutdownHook(new Thread(()->{Map r=new LinkedHashMap();r.put("capture_invalid",invalid);emit("closed",r);}));
 }
 static String hash(byte[]b)throws Exception{StringBuilder s=new StringBuilder();for(byte v:java.security.MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format("%02x",v&255));return s.toString();}
 static String quote(String s){StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray())switch(c){case'"':b.append("\\\"");break;case'\\':b.append("\\\\");break;case'\n':b.append("\\n");break;case'\r':b.append("\\r");break;case'\t':b.append("\\t");break;default:if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}
 static String json(Object v){if(v==null)return"null";if(v instanceof String)return quote((String)v);if(v instanceof Number||v instanceof Boolean)return String.valueOf(v);if(v instanceof List){List<String>a=new ArrayList<>();for(Object x:(List)v)a.add(json(x));return"["+String.join(",",a)+"]";}if(v instanceof Map){List<String>a=new ArrayList<>();for(Object x:((Map)v).entrySet()){Map.Entry e=(Map.Entry)x;a.add(quote((String)e.getKey())+":"+json(e.getValue()));}return"{"+String.join(",",a)+"}";}throw new IllegalArgumentException("No arbitrary object serialization");}
 static synchronized void emit(String kind,Map r){try{Map copy=new LinkedHashMap(r);copy.put("kind",kind);copy.put("seq",++seq);copy.put("thread",Thread.currentThread().getId());copy.put("root",MirrorCapabilityAgent.ROOT.get());try{copy.put("context",MirrorCapabilityTransport.currentContext());}catch(Throwable absent){copy.put("context",Collections.emptyMap());}Files.write(output,(json(copy)+"\n").getBytes(StandardCharsets.UTF_8),StandardOpenOption.APPEND);}catch(Throwable e){invalid=true;System.err.println("BOUNDARY_EXPORT_FAILURE "+e.getClass().getName());}}
 static Map ref(Object v){synchronized(MirrorCapabilityTransport.Evidence.class){Map r=new LinkedHashMap();r.put("object",MirrorCapabilityTransport.Evidence.id(v));r.put("class",v==null?null:v.getClass().getName());if(v==null||v.getClass()==String.class||v.getClass()==Integer.class||v.getClass()==Long.class||v.getClass()==Boolean.class||v.getClass()==Double.class||v.getClass()==Float.class||v.getClass()==Short.class||v.getClass()==Byte.class)r.put("value",v);else if(v.getClass()==Date.class)r.put("epoch_ms",((Date)v).getTime());return r;}}
 static Map snapshot(Object v){Map result=new LinkedHashMap();result.put("value",ref(v));if(MirrorCapabilityAgent.ATOMIC_SOURCE.get()!=null){result.put("fields",Collections.emptyList());result.put("complete",false);result.put("reason","Do not invoke B0 snapshot inside its UUID tagging scope");return result;}try{result.put("fields",MirrorCapabilityAgent.snapshot(v));result.put("complete",true);}catch(Throwable unsupported){result.put("fields",Collections.emptyList());result.put("complete",false);result.put("reason",unsupported.getClass().getName()+":"+unsupported.getMessage());}return result;}
 public static Object begin(String site,String callee,Object receiver,Object[]args,String kind){try{Map r=new LinkedHashMap();synchronized(NativeBoundaryFactsAgent.class){r.put("call_id",++callId);}r.put("site",site);r.put("callee",callee);r.put("effect_kind",kind);r.put("parent_call_id",calls.get().isEmpty()?null:calls.get().peek().get("call_id"));r.put("receiver",ref(receiver));List a=new ArrayList();for(int i=0;i<args.length;i++){Map item=snapshot(args[i]);item.put("argument",i);a.add(item);}r.put("arguments",a);calls.get().push(r);emit("call-begin",r);return r;}catch(Throwable e){invalid=true;emit("problem",Collections.singletonMap("error",e.getClass().getName()));return null;}}
 public static void end(Object token,Object result,Throwable error){if(token==null)return;try{Map r=(Map)token;if(calls.get().isEmpty()||calls.get().peek()!=r)throw new IllegalStateException("Boundary call completion mismatch");calls.get().pop();Map fact=new LinkedHashMap();fact.put("call_id",r.get("call_id"));fact.put("callee",r.get("callee"));fact.put("completion",error==null?"normal":"exceptional");fact.put("result",snapshot(result));fact.put("error",ref(error));emit("call-end",fact);}catch(Throwable e){invalid=true;emit("problem",Collections.singletonMap("error",e.getClass().getName()));}}
 public static void gson(Object converter,Object body,String phase){try{Map r=new LinkedHashMap();r.put("converter",ref(converter));r.put("body",snapshot(body));r.put("phase",phase);Object g=null;for(Class c=converter.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField("gson");f.setAccessible(true);g=f.get(converter);break;}catch(NoSuchFieldException absent){}r.put("gson",ref(g));if(g!=null){Map<String,String>d=definitions.get(g.getClass().getClassLoader());r.put("gson_definition_sha256",d==null?null:d.get("com/google/gson/Gson"));r.put("gson_code_source",g.getClass().getProtectionDomain().getCodeSource()==null?null:String.valueOf(g.getClass().getProtectionDomain().getCodeSource().getLocation()));}r.put("json_projection_certified",false);emit("gson-body-fact",r);}catch(Throwable e){invalid=true;emit("problem",Collections.singletonMap("error",e.getClass().getName()));}}
 public static void write(Object owner,String field){try{MirrorCapabilityTransport.written(owner,field);}catch(Throwable e){invalid=true;}}
 static void box(InsnList x,Type t){MirrorCapabilityAgent.box(x,t);}
 static void wrap(MethodNode m,MethodInsnNode n,String site,String kind){Type[]types=Type.getArgumentTypes(n.desc);Type ret=Type.getReturnType(n.desc);int[]slots=new int[types.length];InsnList before=new InsnList();for(int i=types.length-1;i>=0;i--){slots[i]=m.maxLocals;m.maxLocals+=types[i].getSize();before.add(new VarInsnNode(types[i].getOpcode(ISTORE),slots[i]));}int receiver=m.maxLocals++,token=m.maxLocals++,result=m.maxLocals;m.maxLocals+=Math.max(1,ret.getSize());int error=m.maxLocals++;boolean isStatic=n.getOpcode()==INVOKESTATIC;if(!isStatic)before.add(new VarInsnNode(ASTORE,receiver));before.add(new LdcInsnNode(site));before.add(new LdcInsnNode(n.owner+"."+n.name+n.desc));before.add(new InsnNode(isStatic?ACONST_NULL:NOP));if(!isStatic)before.add(new VarInsnNode(ALOAD,receiver));before.add(new LdcInsnNode(types.length));before.add(new TypeInsnNode(ANEWARRAY,"java/lang/Object"));for(int i=0;i<types.length;i++){before.add(new InsnNode(DUP));before.add(new LdcInsnNode(i));before.add(new VarInsnNode(types[i].getOpcode(ILOAD),slots[i]));box(before,types[i]);before.add(new InsnNode(AASTORE));}before.add(new LdcInsnNode(kind));before.add(new MethodInsnNode(INVOKESTATIC,"NativeBoundaryFactsAgent","begin","(Ljava/lang/String;Ljava/lang/String;Ljava/lang/Object;[Ljava/lang/Object;Ljava/lang/String;)Ljava/lang/Object;",false));before.add(new VarInsnNode(ASTORE,token));if(!isStatic)before.add(new VarInsnNode(ALOAD,receiver));for(int i=0;i<types.length;i++)before.add(new VarInsnNode(types[i].getOpcode(ILOAD),slots[i]));LabelNode start=new LabelNode(),finish=new LabelNode(),handler=new LabelNode(),after=new LabelNode();before.add(start);m.instructions.insertBefore(n,before);InsnList h=new InsnList();h.add(finish);if(ret.getSort()!=Type.VOID)h.add(new VarInsnNode(ret.getOpcode(ISTORE),result));h.add(new VarInsnNode(ALOAD,token));if(ret.getSort()==Type.VOID)h.add(new InsnNode(ACONST_NULL));else{h.add(new VarInsnNode(ret.getOpcode(ILOAD),result));box(h,ret);}h.add(new InsnNode(ACONST_NULL));h.add(new MethodInsnNode(INVOKESTATIC,"NativeBoundaryFactsAgent","end","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Throwable;)V",false));h.add(new JumpInsnNode(GOTO,after));h.add(handler);h.add(new VarInsnNode(ASTORE,error));h.add(new VarInsnNode(ALOAD,token));h.add(new InsnNode(ACONST_NULL));h.add(new VarInsnNode(ALOAD,error));h.add(new MethodInsnNode(INVOKESTATIC,"NativeBoundaryFactsAgent","end","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Throwable;)V",false));h.add(new VarInsnNode(ALOAD,error));h.add(new InsnNode(ATHROW));h.add(after);if(ret.getSort()!=Type.VOID)h.add(new VarInsnNode(ret.getOpcode(ILOAD),result));m.instructions.insert(n,h);m.tryCatchBlocks.add(0,new TryCatchBlockNode(start,finish,handler,"java/lang/Throwable"));}
 public byte[]transform(ClassLoader loader,String owner,Class<?> prior,ProtectionDomain domain,byte[]bytes){try{
  if(owner==null)return null;
  if(runtimeClasses.contains(owner)){synchronized(NativeBoundaryFactsAgent.class){definitions.computeIfAbsent(loader,k->new HashMap<>()).put(owner,hash(bytes));}Map r=new LinkedHashMap();r.put("class",owner);r.put("definition_sha256",hash(bytes));r.put("code_source",domain==null||domain.getCodeSource()==null?null:String.valueOf(domain.getCodeSource().getLocation()));emit("library-definition",r);}
  boolean gson=owner.equals("org/springframework/http/converter/json/GsonHttpMessageConverter");if(!gson&&!owner.startsWith(prefix))return null;
  ClassNode c=new ClassNode(ASM9);new ClassReader(bytes).accept(c,ClassReader.EXPAND_FRAMES);boolean changed=false;
  for(MethodNode m:c.methods){int ordinal=0;for(AbstractInsnNode n:m.instructions.toArray()){
   if(n instanceof MethodInsnNode){MethodInsnNode i=(MethodInsnNode)n;String call=i.owner+"."+i.name+i.desc;if(sinks.contains(call)||reads.contains(call)){wrap(m,i,owner+"."+m.name+m.desc+"#post-native-site:"+ordinal,sinks.contains(call)?"sink":"source-read");changed=true;}}
   if(gson&&m.name.equals("writeInternal")&&m.desc.startsWith("(Ljava/lang/Object;")){if(n.getOpcode()==RETURN){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new LdcInsnNode("write-completed"));h.add(new MethodInsnNode(INVOKESTATIC,"NativeBoundaryFactsAgent","gson","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/String;)V",false));m.instructions.insertBefore(n,h);changed=true;}}
   if(gson&&m.name.equals("readResolved")&&n.getOpcode()==ARETURN){InsnList h=new InsnList();int slot=m.maxLocals++;h.add(new VarInsnNode(ASTORE,slot));h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,slot));h.add(new LdcInsnNode("read-completed"));h.add(new MethodInsnNode(INVOKESTATIC,"NativeBoundaryFactsAgent","gson","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/String;)V",false));h.add(new VarInsnNode(ALOAD,slot));m.instructions.insertBefore(n,h);changed=true;}ordinal++;
  }}if(!changed)return null;
  ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_FRAMES|ClassWriter.COMPUTE_MAXS){protected String getCommonSuperClass(String a,String b){return common(loader,a,b);}};c.accept(w);emit("instrumented",Collections.singletonMap("class",owner));return w.toByteArray();
 }catch(Throwable e){invalid=true;emit("problem",Collections.singletonMap("error",owner+":"+e));return null;}}
 static String parent(ClassLoader l,String n){try(java.io.InputStream in=l==null?ClassLoader.getSystemResourceAsStream(n+".class"):l.getResourceAsStream(n+".class")){if(in==null)return"java/lang/Object";ClassReader c=new ClassReader(in);return c.getSuperName();}catch(Exception e){return"java/lang/Object";}}
 static String common(ClassLoader l,String a,String b){if(a.equals(b))return a;if(a.startsWith("[")&&b.startsWith("[")){String x=a.substring(1),y=b.substring(1);if(x.length()==1||y.length()==1)return"java/lang/Object";String u=x.startsWith("L")?x.substring(1,x.length()-1):x,v=y.startsWith("L")?y.substring(1,y.length()-1):y;String k=common(l,u,v);return"["+(k.startsWith("[")?k:"L"+k+";");}if(a.startsWith("[")||b.startsWith("["))return"java/lang/Object";Set<String>seen=new HashSet<>();for(String n=a;n!=null&&seen.add(n);n=parent(l,n)){}Set<String>visited=new HashSet<>();for(String n=b;n!=null&&visited.add(n);n=parent(l,n))if(seen.contains(n))return n;return"java/lang/Object";}
}
